class Solution {
    fun canPlaceFlowers(flowerbed:IntArray,n:Int):Boolean{
        var remaining=n;
        if(remaining==0)return true;
        for(i in flowerbed.indices)if(flowerbed[i]==0&&(i==0||flowerbed[i-1]==0)&&(i==flowerbed.lastIndex||flowerbed[i+1]==0)){
            flowerbed[i]=1;
            if(--remaining==0)return true
        };
        return false
    }
}

